@namespace sv_712af6b8ed7e475b88d6285d610ed73a.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@Steps[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public int HighestCompletedStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < HighestCompletedStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int index)
    {
        if (index < HighestCompletedStep)
        {
            await OnNavigateToStep.InvokeAsync(index);
        }
    }
}

@namespace sv_712af6b8ed7e475b88d6285d610ed73a.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Company" @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Title" @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate?.ToString("yyyy-MM-dd")" @onchange="e => OnStartDateChanged(e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@EndDate?.ToString("yyyy-MM-dd")" @onchange="e => OnEndDateChanged(e.Value?.ToString())" />
            }
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        var data = BuildData();
        var updated = field switch
        {
            nameof(Company) => data with { Company = value ?? "" },
            nameof(Title) => data with { Title = value ?? "" },
            nameof(Description) => data with { Description = value ?? "" },
            _ => data
        };
        OnChanged.InvokeAsync(updated);
    }

    private void OnStartDateChanged(string? value)
    {
        var date = DateTime.TryParse(value, out var d) ? d : (DateTime?)null;
        OnChanged.InvokeAsync(BuildData() with { StartDate = date });
    }

    private void OnEndDateChanged(string? value)
    {
        var date = DateTime.TryParse(value, out var d) ? d : (DateTime?)null;
        OnChanged.InvokeAsync(BuildData() with { EndDate = date });
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var data = BuildData() with { IsCurrent = isCurrent, EndDate = isCurrent ? null : EndDate };
        await OnChanged.InvokeAsync(data);
    }

    private WorkEntryData BuildData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@namespace sv_712af6b8ed7e475b88d6285d610ed73a.Components.Pages.Apply

<div class="reference-form">
