                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@EndDate?.ToString("yyyy-MM-dd")" @onchange="e => OnEndDateChanged(e.Value?.ToString())" />
            }
        </div>
