@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        var data = BuildData();
        var updated = field switch
        {
            nameof(Company) => data with { Company = value ?? "" },
            nameof(Title) => data with { Title = value ?? "" },
            nameof(Description) => data with { Description = value ?? "" },
            _ => data
        };
        OnChanged.InvokeAsync(updated);
    }

    private void OnStartDateChanged(string? value)
    {
        var date = DateTime.TryParse(value, out var d) ? d : (DateTime?)null;
        OnChanged.InvokeAsync(BuildData() with { StartDate = date });
    }

    private void OnEndDateChanged(string? value)
    {
        var date = DateTime.TryParse(value, out var d) ? d : (DateTime?)null;
        OnChanged.InvokeAsync(BuildData() with { EndDate = date });
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var data = BuildData() with { IsCurrent = isCurrent, EndDate = isCurrent ? null : EndDate };
        await OnChanged.InvokeAsync(data);
    }

    private WorkEntryData BuildData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

