    {
        var data = new ReferenceData(Name, Relationship, Email, Phone);
        var updated = field switch
        {
            nameof(Name) => data with { Name = value ?? "" },
            nameof(Relationship) => data with { Relationship = value ?? "" },
            nameof(Email) => data with { Email = value ?? "" },
            nameof(Phone) => data with { Phone = value ?? "" },
            _ => data
        };
        OnChanged.InvokeAsync(updated);
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

