+@namespace sv_712af6b8ed7e475b88d6285d610ed73a.Components.Pages.Apply
+
+<div class="step-content">
+    <h2>References</h2>
+
+    @if (!string.IsNullOrEmpty(ErrorMessage))
+    {
+        <div class="error-message">@ErrorMessage</div>
+    }
+
+    @for (int i = 0; i < References.Count; i++)
+    {
+        var index = i;
+        var reference = References[index];
+        <fieldset class="entry-group">
+            <legend>Reference @(index + 1)</legend>
+            <ReferenceForm
+                Name="@reference.Name"
+                Relationship="@reference.Relationship"
+                Email="@reference.Email"
+                Phone="@reference.Phone"
+                CanRemove="@(References.Count > 2)"
+                OnRemove="() => RemoveReference(index)"
+                OnChanged="data => UpdateReference(index, data)" />
+        </fieldset>
+    }
+
+    @if (References.Count < 3)
+    {
+        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
+    }
+
+    <div class="step-actions">
+        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
+        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
+    </div>
+</div>
+
+@code {
+    [Parameter] public List<ReferenceModel> References { get; set; } = new();
+    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
+    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
+
+    private string? ErrorMessage;
+
+    protected override void OnInitialized()
+    {
+        while (References.Count < 2)
+            References.Add(new ReferenceModel());
+    }
+
+    private void AddReference()
+    {
+        if (References.Count < 3)
+            References.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index) => References.RemoveAt(index);
+
+    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
+    {
+        References[index] = new ReferenceModel
+        {
+            Name = data.Name,
+            Relationship = data.Relationship,
+            Email = data.Email,
+            Phone = data.Phone
+        };
+    }
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                ErrorMessage = "All reference fields are required.";
+                return;
+            }
+        }
+        await OnNext.InvokeAsync(References);
+    }
+
+    public class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
