@page "/apply"
@using sv_712af6b8ed7e475b88d6285d610ed73a.Components.Pages.Apply
@using sv_712af6b8ed7e475b88d6285d610ed73a.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" HighestCompletedStep="@highestCompletedStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="@workEntries"
                OnNext="HandleWorkNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="@references"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                Personal="@personalResult!"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                OnEdit="NavigateToStep"
                OnBack="GoBack"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int highestCompletedStep;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfoStep.PersonalInfoResult? personalResult;

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new();

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new();

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step < highestCompletedStep)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalResult = result;
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        AdvanceStep();
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        AdvanceStep();
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        AdvanceStep();
    }

    private void AdvanceStep()
    {
        currentStep++;
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalFullName, personalEmail, personalPhone, personalAddress),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

