.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.5rem;
    border: 2px solid #d1d5db;
    background: white;
    color: #6b7280;
    transition: all 0.2s;
}

.step-item.active .step-badge {
    background: #2563eb;
    border-color: #2563eb;
    color: white;
}

.step-item.completed .step-badge {
    background: #10b981;
    border-color: #10b981;
    color: white;
}

.step-item.future .step-badge {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
